// ─── Helpers ─────────────────────────────────────────────────────────────────
// Em desenvolvimento (Vite), usa a porta 3001. Em produção, usa caminhos relativos.
const API = import.meta.env.DEV 
  ? "http://localhost:3001" 
  : window.location.origin;

const uid = () => Math.random().toString(36).slice(2, 9);
const now = () => new Date().toISOString();
const fmt = iso => { if (!iso) return "—"; try { return new Date(iso).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }); } catch { return iso; } };

// ─── API-backed store (syncs to Node.js backend) ────────────────────────────
const accountCache = {}; // { accountId: { data, ts } }

async function fetchAccount(accountId) {
  try {
    const res = await fetch(`${API}/api/account/${accountId}`);
    if (!res.ok) throw new Error(res.status);
    return await res.json();
  } catch {
    return null;
  }
}

async function saveKey(accountId, key, value) {
  try {
    await fetch(`${API}/api/account/${accountId}/${key}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(value),
    });
  } catch (e) {
    console.warn("[API] save failed:", e.message);
  }
}

function useStore(accountId, key, def) {
  const [state, setState] = useState(def);
  const ref = useRef(state);
  ref.current = state;

  // Load from backend on mount and when accountId/key changes
  useEffect(() => {
    let cancelled = false;
    fetchAccount(accountId).then(data => {
      if (cancelled || !data) return;
      setState(data[key] ?? def);
    });
    return () => { cancelled = true; };
  }, [accountId, key]);

  // Poll every 8 seconds to catch incoming webhooks
  useEffect(() => {
    const interval = setInterval(() => {
      fetchAccount(accountId).then(data => {
        if (!data) return;
        setState(prev => {
          const next = data[key] ?? def;
          // Only update if the data actually changed (avoid re-renders)
          return JSON.stringify(next) !== JSON.stringify(prev) ? next : prev;
        });
      });
    }, 8000);
    return () => clearInterval(interval);
  }, [accountId, key]);

  const set = useCallback((v) => {
    const next = typeof v === "function" ? v(ref.current) : v;
    setState(next);
    ref.current = next;
    saveKey(accountId, key, next);
  }, [accountId, key]);

  return [state, set];
}

// ─── Sub-components ───────────────────────────────────────────────────────────
function StatusTag({ status }) {
  const m = { pending: ["Pendente","#FEF3C7","#92400E"], sent: ["Enviado",O.greenPale,"#166534"], failed: ["Falha",O.redPale,"#991B1B"], cancelled: ["Cancelado",O.gray100,O.gray700] };
  const [label, bg, color] = m[status] || [status, O.gray100, O.gray700];
  return <span style={{ ...S.tag, background: bg, color }}>{label}</span>;
}

function Avatar({ name, size = 38 }) {
  const initials = (name || "?").split(" ").slice(0, 2).map(w => w[0]?.toUpperCase()).join("");
  const colors = [O.orange, O.blue, O.green, "#7C3AED", "#DB2777"];
  const color = colors[(name || "").charCodeAt(0) % colors.length] || O.orange;
  return <div style={{ width: size, height: size, borderRadius: size / 2.5, background: color + "22", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><span style={{ fontSize: size * 0.38, fontWeight: 600, color }}>{initials}</span></div>;
}

function Empty({ icon, title, desc }) {
  return <div style={{ textAlign: "center", padding: "64px 24px" }}><div style={{ fontSize: 36, marginBottom: 12, opacity: 0.3 }}>{icon}</div><div style={{ fontSize: 15, fontWeight: 500, color: O.gray700, marginBottom: 6 }}>{title}</div><div style={{ fontSize: 13, color: O.gray400, maxWidth: 320, margin: "0 auto" }}>{desc}</div></div>;
}

function Modal({ title, onClose, children, wide }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.32)", zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center" }} onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: O.white, borderRadius: 20, padding: 28, width: wide ? 700 : 480, maxHeight: "88vh", overflowY: "auto", boxShadow: "0 24px 64px rgba(0,0,0,0.13)" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
          <h2 style={{ fontSize: 17, fontWeight: 600, color: O.black, margin: 0 }}>{title}</h2>
          <button style={{ background: O.gray100, border: "none", borderRadius: 8, width: 28, height: 28, cursor: "pointer", fontSize: 14 }} onClick={onClose}>✕</button>
        </div>
        {children}
      </div>
    </div>
  );
}

function Field({ label, children, style }) {
  return <div style={{ marginBottom: 14, ...style }}><label style={S.label}>{label}</label>{children}</div>;
}

function Actions({ onCancel, onSave, saveLabel = "Salvar" }) {
  return <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 20, paddingTop: 16, borderTop: `1px solid ${O.gray100}` }}><button style={S.btnGhost} onClick={onCancel}>Cancelar</button><button style={S.btn} onClick={onSave}>{saveLabel}</button></div>;
}

