// ─── Dashboard ────────────────────────────────────────────────────────────────
function Dashboard({ accountId }) {
  const [clients]  = useStore(accountId, "clients", []);
  const [messages] = useStore(accountId, "messages", []);
  const [schedules]= useStore(accountId, "schedules", []);
  const [integrations] = useStore(accountId, "integrations", {});

  const pending = schedules.filter(s => s.status === "pending").length;
  const sent    = schedules.filter(s => s.status === "sent").length;

  const stats = [
    { label: "Clientes",         value: clients.length,   color: O.orange },
    { label: "Mensagens",        value: messages.length,  color: O.blue },
    { label: "Ag. pendentes",    value: pending,          color: "#F59E0B" },
    { label: "Enviados",         value: sent,             color: O.green },
  ];

  const recent = [...schedules].sort((a,b) => new Date(b.createdAt)-new Date(a.createdAt)).slice(0,6);

  return (
    <div>
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 24, fontWeight: 600, color: O.black, margin: 0 }}>Painel</h1>
        <p style={{ fontSize: 14, color: O.gray500, marginTop: 4 }}>Conta: <b>{accountId}</b></p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 14, marginBottom: 28 }}>
        {stats.map(s => (
          <div key={s.label} style={{ ...S.card, padding: "18px 20px" }}>
            <div style={{ fontSize: 30, fontWeight: 700, color: s.color }}>{s.value}</div>
            <div style={{ fontSize: 12, color: O.gray500, marginTop: 4 }}>{s.label}</div>
          </div>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 18 }}>
        <div style={S.card}>
          <h3 style={{ fontSize: 14, fontWeight: 600, color: O.black, margin: "0 0 14px" }}>Agendamentos recentes</h3>
          {recent.length === 0
            ? <div style={{ textAlign: "center", padding: "28px 0", color: O.gray400, fontSize: 13 }}>Nenhum agendamento ainda. Cadastre clientes e mensagens para começar.</div>
            : <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
                <thead><tr style={{ borderBottom: `1px solid ${O.gray100}` }}>
                  {["Cliente","Mensagem","Data","Status"].map(h => <th key={h} style={{ textAlign:"left", padding:"5px 8px", color: O.gray500, fontWeight: 500, fontSize: 11 }}>{h}</th>)}
                </tr></thead>
                <tbody>
                  {recent.map(s => (
                    <tr key={s.id} style={{ borderBottom: `1px solid ${O.gray50}` }}>
                      <td style={{ padding:"8px 8px" }}>{s.clientName}</td>
                      <td style={{ padding:"8px 8px", color: O.gray700 }}>{s.messageName}</td>
                      <td style={{ padding:"8px 8px", color: O.gray500 }}>{fmt(s.scheduledAt)}</td>
                      <td style={{ padding:"8px 8px" }}><StatusTag status={s.status} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
          }
        </div>

        <div style={S.card}>
          <h3 style={{ fontSize: 14, fontWeight: 600, color: O.black, margin: "0 0 14px" }}>Integrações</h3>
          {[["chatwoot","Chatwoot","◉"],["whaticket","WhatTicket","◈"]].map(([k,l,ic]) => {
            const cfg = integrations[k];
            const active = cfg?.enabled && cfg?.apiUrl;
            return (
              <div key={k} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"10px 12px", background: O.gray50, borderRadius: 10, marginBottom: 8 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontSize:15 }}>{ic}</span>
                  <span style={{ fontSize:13, fontWeight:500 }}>{l}</span>
                </div>
                <span style={{ ...S.tag, background: active ? O.greenPale : O.gray100, color: active ? "#166534" : O.gray500 }}>{active ? "Ativo" : "Inativo"}</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ─── Clients ─────────────────────────────────────────────────────────────────
function Clients({ accountId }) {
  const [clients, setClients] = useStore(accountId, "clients", []);
  const [show, setShow] = useState(false);
  const [editId, setEditId] = useState(null);
  const [search, setSearch] = useState("");
  const blank = { name:"", phone:"", email:"", notes:"", source:"manual", tags:"" };
  const [form, setForm] = useState(blank);

  const filtered = clients.filter(c =>
    (c.name||"").toLowerCase().includes(search.toLowerCase()) ||
    (c.phone||"").includes(search) ||
    (c.email||"").toLowerCase().includes(search.toLowerCase())
  );

  function openNew()  { setForm(blank); setEditId(null); setShow(true); }
  function openEdit(c){ setForm({...c, tags:(c.tags||[]).join(", ")}); setEditId(c.id); setShow(true); }

  function save() {
    if (!form.name.trim()) return;
    const tags = form.tags.split(",").map(t=>t.trim()).filter(Boolean);
    if (editId) {
      setClients(cs => cs.map(c => c.id === editId ? {...c, ...form, tags, updatedAt:now()} : c));
    } else {
      setClients(cs => [...cs, {...form, tags, id:uid(), createdAt:now()}]);
    }
    setShow(false);
  }

  function remove(id) { if (confirm("Remover este cliente?")) setClients(cs => cs.filter(c => c.id !== id)); }

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:24 }}>
        <div>
          <h1 style={{ fontSize:24, fontWeight:600, color:O.black, margin:0 }}>Clientes</h1>
          <p style={{ fontSize:14, color:O.gray500, marginTop:4 }}>{clients.length} clientes cadastrados</p>
        </div>
        <button style={S.btn} onClick={openNew}>+ Novo cliente</button>
      </div>

      <input style={{ ...S.input, marginBottom:14 }} placeholder="Buscar por nome, telefone ou e-mail..." value={search} onChange={e => setSearch(e.target.value)} />

      {filtered.length === 0
        ? <Empty icon="◉" title="Nenhum cliente ainda" desc="Cadastre seu primeiro cliente ou configure uma integração para importar automaticamente." />
        : <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {filtered.map(c => (
              <div key={c.id} style={{ ...S.cardSm, display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                <div style={{ display:"flex", alignItems:"center", gap:14 }}>
                  <Avatar name={c.name} />
                  <div>
                    <div style={{ fontSize:14, fontWeight:500, color:O.black }}>{c.name}</div>
                    <div style={{ fontSize:12, color:O.gray500, marginTop:2 }}>{[c.phone,c.email].filter(Boolean).join(" · ")}</div>
                    <div style={{ display:"flex", gap:6, marginTop:4, flexWrap:"wrap", alignItems:"center" }}>
                      {(c.tags||[]).map(t => <span key={t} style={{ ...S.tag, background:O.orangePale, color:O.orange, fontSize:10 }}>{t}</span>)}
                      {c.messagesReceived > 0 && (
                        <span style={{ ...S.tag, background:O.bluePale, color:O.blue, fontSize:10 }}>📨 {c.messagesReceived} msg{c.messagesReceived > 1 ? "s" : ""} recebida{c.messagesReceived > 1 ? "s" : ""}</span>
                      )}
                      {c.lastWebhookAt && (
                        <span style={{ fontSize:10, color:O.gray400 }}>Último webhook: {fmt(c.lastWebhookAt)}</span>
                      )}
                    </div>
                  </div>
                </div>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ ...S.tag, background:O.gray50, color:O.gray400, fontSize:10 }}>{c.source||"manual"}</span>
                  {c.chatwootUrl && (
                    <a href={c.chatwootUrl} target="_blank" rel="noreferrer"
                       style={{ ...S.btnGhost, textDecoration:"none", fontSize:12, padding:"6px 12px", color:"#2563EB", borderColor:"#BFDBFE", background:"#EFF6FF" }}>
                      ◉ Abrir no Chatwoot
                    </a>
                  )}
                  <button style={S.btnGhost} onClick={()=>openEdit(c)}>Editar</button>
                  <button style={{ ...S.btnGhost, color:O.red, borderColor:"#FECACA" }} onClick={()=>remove(c.id)}>✕</button>
                </div>
              </div>
            ))}
          </div>
      }

      {show && (
        <Modal title={editId ? "Editar cliente" : "Novo cliente"} onClose={()=>setShow(false)}>
          <Field label="Nome *"><input style={S.input} value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="Nome completo" /></Field>
          <Field label="Telefone / WhatsApp"><input style={S.input} value={form.phone} onChange={e=>setForm(f=>({...f,phone:e.target.value}))} placeholder="+55 11 99999-9999" /></Field>
          <Field label="E-mail"><input style={S.input} value={form.email} onChange={e=>setForm(f=>({...f,email:e.target.value}))} placeholder="cliente@email.com" /></Field>
          <Field label="Tags (separadas por vírgula)"><input style={S.input} value={form.tags} onChange={e=>setForm(f=>({...f,tags:e.target.value}))} placeholder="vip, lead, proposta" /></Field>
          <Field label="Observações"><textarea style={{ ...S.input, resize:"vertical", minHeight:80 }} value={form.notes} onChange={e=>setForm(f=>({...f,notes:e.target.value}))} placeholder="Anotações sobre o cliente..." /></Field>
          <Actions onCancel={()=>setShow(false)} onSave={save} />
        </Modal>
      )}
    </div>
  );
}

// ─── Messages ────────────────────────────────────────────────────────────────
const VARS = ["{{nome}}","{{telefone}}","{{email}}","{{data}}","{{hora}}"];

function Messages({ accountId }) {
  const [messages, setMessages] = useStore(accountId, "messages", []);
  const [show, setShow] = useState(false);
  const [editId, setEditId] = useState(null);
  const blank = { name:"", content:"", channel:"whatsapp", type:"text" };
  const [form, setForm] = useState(blank);

  function openNew()  { setForm(blank); setEditId(null); setShow(true); }
  function openEdit(m){ setForm(m); setEditId(m.id); setShow(true); }

  function save() {
    if (!form.name.trim() || !form.content.trim()) return;
    if (editId) {
      setMessages(ms => ms.map(m => m.id === editId ? {...m,...form,updatedAt:now()} : m));
    } else {
      setMessages(ms => [...ms, {...form, id:uid(), createdAt:now()}]);
    }
    setShow(false);
  }

  function remove(id) { if (confirm("Remover mensagem?")) setMessages(ms => ms.filter(m => m.id !== id)); }

  const preview = (txt) => txt
    .replaceAll("{{nome}}", "João Silva")
    .replaceAll("{{telefone}}", "11 99999-9999")
    .replaceAll("{{email}}", "joao@email.com")
    .replaceAll("{{data}}", new Date().toLocaleDateString("pt-BR"))
    .replaceAll("{{hora}}", "10:00");

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:24 }}>
        <div>
          <h1 style={{ fontSize:24, fontWeight:600, color:O.black, margin:0 }}>Mensagens</h1>
          <p style={{ fontSize:14, color:O.gray500, marginTop:4 }}>Templates reutilizáveis para follow-up</p>
        </div>
        <button style={S.btn} onClick={openNew}>+ Nova mensagem</button>
      </div>

      <div style={{ marginBottom:16, padding:"12px 16px", background:O.orangePale, borderRadius:12, fontSize:13, color:O.gray700, display:"flex", alignItems:"center", gap:8 }}>
        <span style={{ color:O.orange }}>◈</span>
        Use variáveis para personalizar: <b>{"{{nome}}"}</b>, <b>{"{{telefone}}"}</b>, <b>{"{{data}}"}</b>, <b>{"{{hora}}"}</b>
      </div>

      {messages.length === 0
        ? <Empty icon="◈" title="Nenhuma mensagem criada" desc="Crie templates de mensagens para usar nos agendamentos." />
        : <div style={{ display:"grid", gridTemplateColumns:"repeat(2,1fr)", gap:12 }}>
            {messages.map(m => (
              <div key={m.id} style={S.card}>
                <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", marginBottom:10 }}>
                  <div>
                    <div style={{ fontSize:14, fontWeight:600, color:O.black }}>{m.name}</div>
                    <div style={{ display:"flex", gap:6, marginTop:4 }}>
                      <span style={{ ...S.tag, background:O.orangePale, color:O.orange }}>{m.channel}</span>
                      <span style={{ ...S.tag, background:O.gray50, color:O.gray500 }}>{m.type}</span>
                    </div>
                  </div>
                  <div style={{ display:"flex", gap:6 }}>
                    <button style={S.btnGhost} onClick={()=>openEdit(m)}>Editar</button>
                    <button style={{ ...S.btnGhost, color:O.red, borderColor:"#FECACA" }} onClick={()=>remove(m.id)}>✕</button>
                  </div>
                </div>
                <div style={{ fontSize:13, color:O.gray700, background:O.gray50, borderRadius:8, padding:"10px 12px", whiteSpace:"pre-wrap", maxHeight:90, overflow:"hidden" }}>{m.content}</div>
                <div style={{ fontSize:11, color:O.gray400, marginTop:8 }}>Criada {fmt(m.createdAt)}</div>
              </div>
            ))}
          </div>
      }

      {show && (
        <Modal title={editId ? "Editar mensagem" : "Nova mensagem"} onClose={()=>setShow(false)} wide>
          <Field label="Nome do template *">
            <input style={S.input} value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="Ex: Boas-vindas, Follow-up 3 dias..." />
          </Field>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12 }}>
            <Field label="Canal">
              <select style={S.input} value={form.channel} onChange={e=>setForm(f=>({...f,channel:e.target.value}))}>
                <option value="whatsapp">WhatsApp</option>
                <option value="email">E-mail</option>
                <option value="sms">SMS</option>
              </select>
            </Field>
            <Field label="Tipo">
              <select style={S.input} value={form.type} onChange={e=>setForm(f=>({...f,type:e.target.value}))}>
                <option value="text">Texto</option>
                <option value="template">Template oficial</option>
                <option value="interactive">Interativo</option>
              </select>
            </Field>
          </div>
          <Field label="Conteúdo *">
            <div style={{ marginBottom:6, display:"flex", gap:4, flexWrap:"wrap" }}>
              {VARS.map(v => <button key={v} style={{ ...S.btnGhost, padding:"3px 8px", fontSize:11 }} onClick={()=>setForm(f=>({...f,content:f.content+v}))}>{v}</button>)}
            </div>
            <textarea style={{ ...S.input, minHeight:130, resize:"vertical" }} value={form.content} onChange={e=>setForm(f=>({...f,content:e.target.value}))} placeholder={"Olá {{nome}}, tudo bem? Passando para dar um retorno..."} />
          </Field>
          {form.content && (
            <Field label="Pré-visualização (com dados de exemplo)">
              <div style={{ background:O.orangePale, borderRadius:12, padding:"12px 16px", fontSize:13, color:O.black, whiteSpace:"pre-wrap" }}>{preview(form.content)}</div>
            </Field>
          )}
          <Actions onCancel={()=>setShow(false)} onSave={save} />
        </Modal>
      )}
    </div>
  );
}

// ─── Schedules ────────────────────────────────────────────────────────────────
function Schedules({ accountId }) {
  const [schedules, setSchedules] = useStore(accountId, "schedules", []);
  const [clients]  = useStore(accountId, "clients", []);
  const [messages] = useStore(accountId, "messages", []);
  const [show, setShow] = useState(false);
  const [filterStatus, setFilterStatus] = useState("all");
  const [editId, setEditId] = useState(null);
  const blank = { clientId:"", messageId:"", scheduledAt:"", notes:"", repeat:"none" };
  const [form, setForm] = useState(blank);

  const filtered = schedules.filter(s => filterStatus === "all" || s.status === filterStatus);

  function openNew()  { setForm(blank); setEditId(null); setShow(true); }
  function openEdit(s){ setForm(s); setEditId(s.id); setShow(true); }

  function save() {
    if (!form.clientId || !form.messageId || !form.scheduledAt) return;
    const client  = clients.find(c => c.id === form.clientId);
    const message = messages.find(m => m.id === form.messageId);
    if (editId) {
      setSchedules(ss => ss.map(s => s.id === editId ? {...s,...form, clientName:client?.name, messageName:message?.name, updatedAt:now()} : s));
    } else {
      setSchedules(ss => [...ss, {...form, id:uid(), status:"pending", createdAt:now(), clientName:client?.name||"?", messageName:message?.name||"?"}]);
    }
    setShow(false);
  }

  function markSent(id) { setSchedules(ss => ss.map(s => s.id===id ? {...s, status:"sent", sentAt:now()} : s)); }
  function cancel(id)   { setSchedules(ss => ss.map(s => s.id===id ? {...s, status:"cancelled"} : s)); }
  function remove(id)   { if (confirm("Remover agendamento?")) setSchedules(ss => ss.filter(s => s.id !== id)); }

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:24 }}>
        <div>
          <h1 style={{ fontSize:24, fontWeight:600, color:O.black, margin:0 }}>Agendamentos</h1>
          <p style={{ fontSize:14, color:O.gray500, marginTop:4 }}>{schedules.length} agendamentos no total</p>
        </div>
        <button style={S.btn} onClick={openNew}>+ Agendar follow-up</button>
      </div>

      <div style={{ display:"flex", gap:8, marginBottom:16 }}>
        {[["all","Todos"],["pending","Pendentes"],["sent","Enviados"],["failed","Falha"],["cancelled","Cancelados"]].map(([v,l]) => (
          <button key={v} style={{ ...(filterStatus===v ? S.btn : S.btnGhost), padding:"6px 14px" }} onClick={()=>setFilterStatus(v)}>{l}</button>
        ))}
      </div>

      {filtered.length === 0
        ? <Empty icon="◷" title="Nenhum agendamento" desc="Crie agendamentos de follow-up para seus clientes." />
        : <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {filtered.map(s => (
              <div key={s.id} style={{ ...S.cardSm, display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                <div style={{ display:"flex", alignItems:"center", gap:14 }}>
                  <div style={{ width:38, height:38, borderRadius:10, background: s.status==="sent" ? O.greenPale : s.status==="failed" ? O.redPale : O.orangePale, display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, flexShrink:0 }}>
                    {s.status==="sent" ? "✓" : s.status==="failed" ? "✕" : "◷"}
                  </div>
                  <div>
                    <div style={{ fontSize:14, fontWeight:500, color:O.black }}>{s.clientName}</div>
                    <div style={{ fontSize:12, color:O.gray500 }}>{s.messageName} · {fmt(s.scheduledAt)}</div>
                    {s.notes && <div style={{ fontSize:11, color:O.gray400, marginTop:2 }}>{s.notes}</div>}
                  </div>
                </div>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <StatusTag status={s.status} />
                  {s.status==="pending" && <button style={S.btnGhost} onClick={()=>markSent(s.id)}>✓ Enviado</button>}
                  {s.status==="pending" && <button style={S.btnGhost} onClick={()=>cancel(s.id)}>Cancelar</button>}
                  <button style={{ ...S.btnGhost, padding:"6px 10px" }} onClick={()=>openEdit(s)}>✎</button>
                  <button style={{ ...S.btnGhost, color:O.red, borderColor:"#FECACA", padding:"6px 10px" }} onClick={()=>remove(s.id)}>✕</button>
                </div>
              </div>
            ))}
          </div>
      }

      {show && (
        <Modal title={editId ? "Editar agendamento" : "Novo agendamento"} onClose={()=>setShow(false)}>
          <Field label="Cliente *">
            <select style={S.input} value={form.clientId} onChange={e=>setForm(f=>({...f,clientId:e.target.value}))}>
              <option value="">Selecione um cliente...</option>
              {clients.map(c => <option key={c.id} value={c.id}>{c.name}{c.phone ? ` — ${c.phone}` : ""}</option>)}
            </select>
            {clients.length===0 && <div style={{ fontSize:11, color:O.orange, marginTop:4 }}>⚠ Nenhum cliente cadastrado ainda.</div>}
          </Field>
          <Field label="Mensagem / Template *">
            <select style={S.input} value={form.messageId} onChange={e=>setForm(f=>({...f,messageId:e.target.value}))}>
              <option value="">Selecione uma mensagem...</option>
              {messages.map(m => <option key={m.id} value={m.id}>{m.name} ({m.channel})</option>)}
            </select>
            {messages.length===0 && <div style={{ fontSize:11, color:O.orange, marginTop:4 }}>⚠ Nenhuma mensagem criada ainda.</div>}
          </Field>
          <Field label="Data e hora de envio *">
            <input type="datetime-local" style={S.input} value={form.scheduledAt?.slice(0,16)||""} onChange={e=>setForm(f=>({...f,scheduledAt:e.target.value}))} />
          </Field>
          <Field label="Repetição">
            <select style={S.input} value={form.repeat} onChange={e=>setForm(f=>({...f,repeat:e.target.value}))}>
              <option value="none">Não repetir</option>
              <option value="daily">Diariamente</option>
              <option value="weekly">Semanalmente</option>
              <option value="monthly">Mensalmente</option>
            </select>
          </Field>
          <Field label="Observação interna">
            <input style={S.input} value={form.notes||""} onChange={e=>setForm(f=>({...f,notes:e.target.value}))} placeholder="Nota sobre esse follow-up..." />
          </Field>
          <Actions onCancel={()=>setShow(false)} onSave={save} />
        </Modal>
      )}
    </div>
  );
}

// ─── Webhooks ────────────────────────────────────────────────────────────────
function Webhooks({ accountId }) {
  const [webhooks, setWebhooks] = useStore(accountId, "webhooks", []);
  const [logs, setLogs]         = useStore(accountId, "webhookLogs", []);
  const [messages]              = useStore(accountId, "messages", []);
  const [clients, setClients]   = useStore(accountId, "clients", []);
  const [schedules, setSchedules] = useStore(accountId, "schedules", []);
  const [show, setShow] = useState(false);
  const blank = { name:"", description:"", autoSchedule:false, defaultMessageId:"", scheduleDays:1, active:true };
  const [form, setForm] = useState(blank);

  const baseUrl = `${API}/api/webhook`;

  function save() {
    if (!form.name.trim()) return;
    setWebhooks(ws => [...ws, {...form, id:uid(), createdAt:now(), token:uid()+uid()}]);
    setShow(false);
    setForm(blank);
  }

  function remove(id) { if (confirm("Remover webhook?")) setWebhooks(ws => ws.filter(w => w.id !== id)); }
  function toggle(id) { setWebhooks(ws => ws.map(w => w.id===id ? {...w, active:!w.active} : w)); }

  // Simula recepção de um payload do Chatwoot e processa localmente
  function simulate(wh) {
    const contact = { name:"Cliente Webhook", phone_number:"+5511988887777", email:"webhook@teste.com" };
    const payload = { event:"contact_created", account:{id:1}, contact:{...contact, id:Date.now()} };

    // Cadastra cliente se não existir
    const already = clients.find(c => c.phone === contact.phone_number);
    if (!already) {
      const newClient = { id:uid(), name:contact.name, phone:contact.phone_number, email:contact.email, source:"webhook", tags:["webhook"], notes:"Cadastrado automaticamente via webhook", createdAt:now() };
      setClients(cs => [...cs, newClient]);

      // Agenda follow-up se configurado
      if (wh.autoSchedule && wh.defaultMessageId) {
        const msg = messages.find(m => m.id === wh.defaultMessageId);
        const dt = new Date();
        dt.setDate(dt.getDate() + (wh.scheduleDays || 1));
        setSchedules(ss => [...ss, { id:uid(), clientId:newClient.id, clientName:newClient.name, messageId:wh.defaultMessageId, messageName:msg?.name||"?", scheduledAt:dt.toISOString(), status:"pending", repeat:"none", notes:"Criado automaticamente via webhook", createdAt:now() }]);
      }
    }

    const log = { id:uid(), webhookId:wh.id, webhookName:wh.name, receivedAt:now(), payload, status:"processed", action: already ? "Cliente já existia, ignorado" : (wh.autoSchedule ? "Cliente cadastrado + follow-up agendado" : "Cliente cadastrado") };
    setLogs(ls => [log, ...ls].slice(0,100));
    alert(`✓ Simulação processada!\n\nPayload recebido.\nAção: ${log.action}\n\nVeja na aba Clientes e Agendamentos.`);
  }

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:24 }}>
        <div>
          <h1 style={{ fontSize:24, fontWeight:600, color:O.black, margin:0 }}>Webhooks</h1>
          <p style={{ fontSize:14, color:O.gray500, marginTop:4 }}>Receba eventos e cadastre clientes automaticamente</p>
        </div>
        <button style={S.btn} onClick={()=>{setForm(blank);setShow(true);}}>+ Criar webhook</button>
      </div>

      <div style={{ padding:"14px 16px", background:O.bluePale, borderRadius:12, marginBottom:20, fontSize:13, color:"#1E40AF" }}>
        <b>Como funciona:</b> Cada webhook gera uma URL única. Configure-a no Chatwoot ou WhatTicket para que, ao criar um contato ou conversa, o cliente seja cadastrado aqui automaticamente — e um follow-up agendado, se quiser.
      </div>

      {webhooks.length === 0
        ? <Empty icon="⬡" title="Nenhum webhook criado" desc="Crie webhooks para automatizar o cadastro de clientes a partir do Chatwoot ou WhatTicket." />
        : <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
            {webhooks.map(wh => (
              <div key={wh.id} style={S.card}>
                <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between" }}>
                  <div style={{ flex:1 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
                      <span style={{ fontSize:15, fontWeight:600, color:O.black }}>{wh.name}</span>
                      <span style={{ ...S.tag, background: wh.active ? O.greenPale : O.gray100, color: wh.active ? "#166534" : O.gray500 }}>{wh.active ? "Ativo" : "Inativo"}</span>
                    </div>
                    {wh.description && <div style={{ fontSize:13, color:O.gray500, marginBottom:8 }}>{wh.description}</div>}
                    <div style={{ fontSize:12, color:O.gray500, marginBottom:4 }}>URL para configurar no Chatwoot/WhatTicket:</div>
                    <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                      <code style={{ fontSize:11, background:O.gray50, padding:"6px 12px", borderRadius:8, color:O.black, flex:1, wordBreak:"break-all" }}>{baseUrl}/{accountId}/{wh.token}</code>
                      <button style={S.btnGhost} onClick={()=>{navigator.clipboard?.writeText(`${baseUrl}/${accountId}/${wh.token}`);alert("URL copiada!");}}>Copiar</button>
                    </div>
                    <div style={{ marginTop:8, fontSize:12, color:O.gray500 }}>
                      {wh.autoSchedule ? `✓ Agenda follow-up automaticamente ${wh.scheduleDays} dia(s) após o contato` : "Apenas cadastra o cliente"}
                    </div>
                  </div>
                  <div style={{ display:"flex", gap:6, marginLeft:16 }}>
                    <button style={S.btnGhost} onClick={()=>simulate(wh)}>Simular</button>
                    <button style={S.btnGhost} onClick={()=>toggle(wh.id)}>{wh.active?"Pausar":"Ativar"}</button>
                    <button style={{ ...S.btnGhost, color:O.red, borderColor:"#FECACA" }} onClick={()=>remove(wh.id)}>✕</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
      }

      {logs.length > 0 && (
        <div style={{ marginTop:28 }}>
          <h2 style={{ fontSize:15, fontWeight:600, color:O.black, marginBottom:10 }}>Log de eventos ({logs.length})</h2>
          <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
            {logs.slice(0,20).map(l => (
              <div key={l.id} style={{ ...S.cardSm, display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                <div>
                  <span style={{ fontSize:13, fontWeight:500, color:O.black }}>{l.webhookName}</span>
                  <span style={{ fontSize:12, color:O.gray500, marginLeft:10 }}>{l.action}</span>
                </div>
                <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                  <StatusTag status={l.status==="processed" ? "sent" : "failed"} />
                  <span style={{ fontSize:11, color:O.gray400 }}>{fmt(l.receivedAt)}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {show && (
        <Modal title="Criar webhook" onClose={()=>setShow(false)}>
          <Field label="Nome do webhook *">
            <input style={S.input} value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder="Ex: Chatwoot — Novos contatos" />
          </Field>
          <Field label="Descrição">
            <input style={S.input} value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} placeholder="Para que serve este webhook?" />
          </Field>
          <div style={{ padding:14, background:O.orangePale, borderRadius:10, marginBottom:14 }}>
            <label style={{ display:"flex", alignItems:"center", gap:10, cursor:"pointer" }}>
              <input type="checkbox" checked={form.autoSchedule} onChange={e=>setForm(f=>({...f,autoSchedule:e.target.checked}))} />
              <div>
                <div style={{ fontSize:13, fontWeight:500, color:O.black }}>Criar agendamento automático</div>
                <div style={{ fontSize:12, color:O.gray700 }}>Quando o cliente chegar, agenda follow-up automaticamente</div>
              </div>
            </label>
          </div>
          {form.autoSchedule && (
            <>
              <Field label="Mensagem padrão">
                <select style={S.input} value={form.defaultMessageId} onChange={e=>setForm(f=>({...f,defaultMessageId:e.target.value}))}>
                  <option value="">Selecione...</option>
                  {messages.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                </select>
              </Field>
              <Field label="Agendar após quantos dias?">
                <input type="number" min={0} style={{ ...S.input, width:100 }} value={form.scheduleDays} onChange={e=>setForm(f=>({...f,scheduleDays:parseInt(e.target.value)||1}))} />
              </Field>
            </>
          )}
          <Actions onCancel={()=>setShow(false)} onSave={save} saveLabel="Criar webhook" />
        </Modal>
      )}
    </div>
  );
}

// ─── Chatwoot API helper ──────────────────────────────────────────────────────
async function cwReq(apiUrl, apiToken, path, method="GET", body=null) {
  let formattedUrl = apiUrl.replace(/\/$/, "");
  if (!formattedUrl.startsWith("http://") && !formattedUrl.startsWith("https://")) {
    formattedUrl = "https://" + formattedUrl;
  }
  const url = `${formattedUrl}${path}`;
  const opts = { method, headers: { "api_access_token": apiToken, "Content-Type": "application/json" } };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(url, opts);
  if (!res.ok) { const t = await res.text().catch(()=>""); throw new Error(`HTTP ${res.status}: ${t.slice(0,200)}`); }
  return res.json();
}

// ─── Integrations ────────────────────────────────────────────────────────────
function Integrations({ accountId }) {
  const [integrations, setIntegrations] = useStore(accountId, "integrations", {});
  const [active, setActive] = useState("chatwoot");
  const update = (key, data) => setIntegrations(i => ({...i, [key]: {...i[key], ...data}}));
  const tabs = [["chatwoot","Chatwoot"],["whaticket","WhatTicket"]];

  return (
    <div>
      <div style={{ marginBottom:24 }}>
        <h1 style={{ fontSize:24, fontWeight:600, color:O.black, margin:0 }}>Integrações</h1>
        <p style={{ fontSize:14, color:O.gray500, marginTop:4 }}>Conecte com suas plataformas de atendimento</p>
      </div>
      <div style={{ display:"flex", gap:8, marginBottom:24, borderBottom:`1px solid ${O.gray100}` }}>
        {tabs.map(([id,l]) => (
          <button key={id} onClick={()=>setActive(id)} style={{ padding:"10px 20px", border:"none", background:"transparent", cursor:"pointer", fontSize:14, fontFamily:"inherit", fontWeight: active===id ? 600 : 400, color: active===id ? O.orange : O.gray500, borderBottom: active===id ? `2px solid ${O.orange}` : "2px solid transparent", marginBottom:-1 }}>{l}</button>
        ))}
      </div>
      {active === "chatwoot" && <ChatwootConfig cfg={integrations.chatwoot||{}} onChange={d=>update("chatwoot",d)} accountId={accountId} />}
      {active === "whaticket" && <WhaticketConfig cfg={integrations.whaticket||{}} onChange={d=>update("whaticket",d)} />}
    </div>
  );
}

function ChatwootConfig({ cfg, onChange, accountId: followupAccountId }) {
  const [clients, setClients] = useStore(followupAccountId, "clients", []);
  const [form, setForm] = useState({...cfg});
  const [saved, setSaved] = useState(false);
  const [connStatus, setConnStatus] = useState(null);
  const [whStatus, setWhStatus]     = useState(null);
  const [contactSearch, setContactSearch] = useState("");
  const [contactResults, setContactResults] = useState(null);
  const [importing, setImporting] = useState({});
  const [inboxes, setInboxes] = useState(null);
  const [activeTab, setActiveTab] = useState("connection");

  const ready = !!(form.apiUrl && form.apiToken && form.cwAccountId);

  function saveForm() {
    onChange({...form, updatedAt:now()});
    setSaved(true);
    setTimeout(()=>setSaved(false), 2000);
  }

  async function testConnection() {
    if (!ready) { setConnStatus({ok:false, msg:"Preencha URL, token e ID da conta primeiro."}); return; }
    setConnStatus("loading");
    try {
      // Attempt 1: profile
      const data = await cwReq(form.apiUrl, form.apiToken, "/api/v1/profile");
      const name = data?.name || data?.email || "usuário";
      setConnStatus({ok:true, msg:`Conectado! Usuário: ${name}`, data});
      // Fetch inboxes while we are connected
      try {
        const ix = await cwReq(form.apiUrl, form.apiToken, `/api/v1/accounts/${form.cwAccountId}/inboxes`);
        setInboxes(ix?.payload || []);
      } catch {}
    } catch(e1) {
      try {
        // Attempt 2: account info
        const data = await cwReq(form.apiUrl, form.apiToken, `/api/v1/accounts/${form.cwAccountId}`);
        setConnStatus({ok:true, msg:`Conta encontrada: ${data?.name || form.cwAccountId}`, data});
      } catch(e2) {
        const isCors = e2.message.includes("Failed to fetch") || e2.message.includes("NetworkError");
        setConnStatus({ok:false, msg: isCors
          ? "Não foi possível conectar (CORS ou URL inválida). Verifique se: 1) A URL está correta; 2) O Chatwoot permite esta origem; 3) O token é válido."
          : `Erro: ${e2.message}`});
      }
    }
  }

  async function testWebhook() {
    if (!ready) { setWhStatus({ok:false, msg:"Salve as credenciais antes de testar."}); return; }
    setWhStatus("loading");
    const samplePayload = { event:"contact_created", account:{id:parseInt(form.cwAccountId)||1}, contact:{id:9999, name:"Contato Teste", phone_number:"+5511999999999", email:"teste@followup.com", created_at:now()} };
    try {
      let cwWebhooks = [];
      try { const d = await cwReq(form.apiUrl, form.apiToken, `/api/v1/accounts/${form.cwAccountId}/integrations/webhooks`); cwWebhooks = d?.payload||[]; } catch {}
      setWhStatus({ ok:true, msg: cwWebhooks.length > 0 ? `Chatwoot tem ${cwWebhooks.length} webhook(s) configurado(s).` : "Nenhum webhook encontrado no Chatwoot ainda — configure a URL da aba Webhooks.", payload:samplePayload, cwWebhooks });
    } catch(e) {
      setWhStatus({ ok:false, msg:`Erro: ${e.message}`, payload:samplePayload });
    }
  }

  async function searchContacts() {
    if (!ready) return;
    setContactResults("loading");
    try {
      const path = contactSearch.trim()
        ? `/api/v1/accounts/${form.cwAccountId}/contacts/search?q=${encodeURIComponent(contactSearch)}&page=1`
        : `/api/v1/accounts/${form.cwAccountId}/contacts?page=1`;
      const data = await cwReq(form.apiUrl, form.apiToken, path);
      setContactResults(data?.payload || data?.contacts || []);
    } catch(e) {
      setContactResults([]);
      alert(`Erro ao buscar contatos: ${e.message}`);
    }
  }

  function importContact(c) {
    const id = c.id;
    setImporting(i=>({...i,[id]:true}));
    const already = clients.find(cl => cl.chatwootId===id || cl.phone===c.phone_number);
    if (already) { alert(`"${c.name}" já está cadastrado.`); setImporting(i=>({...i,[id]:false})); return; }
    setClients(cs => [...cs, { id:uid(), name:c.name||"Sem nome", phone:c.phone_number||"", email:c.email||"", notes:`Importado do Chatwoot em ${fmt(now())}`, source:"chatwoot", chatwootId:id, tags:["chatwoot"], createdAt:now() }]);
    setTimeout(()=>setImporting(i=>({...i,[id]:false})), 500);
  }

  function Tab(id, label) {
    return <button onClick={()=>setActiveTab(id)} style={{ padding:"8px 16px", border:"none", background:"transparent", cursor:"pointer", fontSize:13, fontFamily:"inherit", fontWeight:activeTab===id?600:400, color:activeTab===id?O.orange:O.gray500, borderBottom:activeTab===id?`2px solid ${O.orange}`:"2px solid transparent", marginBottom:-1 }}>{label}</button>;
  }

  return (
    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:24 }}>
      <div>
        <div style={{ ...S.card, marginBottom:16 }}>
          <h3 style={{ fontSize:15, fontWeight:600, color:O.black, margin:"0 0 16px" }}>Credenciais</h3>
          <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", marginBottom:16 }}>
            <input type="checkbox" checked={!!form.enabled} onChange={e=>setForm(f=>({...f,enabled:e.target.checked}))} />
            <span style={{ fontSize:13, fontWeight:500 }}>Integração ativa</span>
          </label>
          <Field label="URL do Chatwoot"><input style={S.input} value={form.apiUrl||""} onChange={e=>setForm(f=>({...f,apiUrl:e.target.value.replace(/\/$/,"")}))} placeholder="https://app.chatwoot.com" /></Field>
          <Field label="User Access Token"><input type="password" style={S.input} value={form.apiToken||""} onChange={e=>setForm(f=>({...f,apiToken:e.target.value}))} placeholder="Token de acesso do usuário" /></Field>
          <Field label="Account ID"><input style={S.input} value={form.cwAccountId||""} onChange={e=>setForm(f=>({...f,cwAccountId:e.target.value}))} placeholder="Ex: 1  (Settings → Account Settings)" /></Field>
          {inboxes && inboxes.length > 0 && (
            <Field label="Inbox padrão (detectada automaticamente)">
              <select style={S.input} value={form.inboxId||""} onChange={e=>setForm(f=>({...f,inboxId:e.target.value}))}>
                <option value="">Selecione...</option>
                {inboxes.map(i => <option key={i.id} value={i.id}>{i.name} ({i.channel_type})</option>)}
              </select>
            </Field>
          )}
          <button style={S.btn} onClick={saveForm}>{saved ? "✓ Salvo!" : "Salvar credenciais"}</button>
        </div>

        <div style={S.card}>
          <h3 style={{ fontSize:15, fontWeight:600, color:O.black, margin:"0 0 8px" }}>Automações</h3>
          <p style={{ fontSize:13, color:O.gray500, marginBottom:14 }}>O que acontece quando eventos chegam via webhook</p>
          {[
            {key:"autoImportContacts", label:"Importar contatos via webhook", desc:"Ao receber contact_created, cadastra o cliente aqui"},
            {key:"autoScheduleOnNew",  label:"Agendar follow-up automático",  desc:"Junto ao cadastro, cria agendamento com a mensagem padrão"},
            {key:"syncStatus",         label:"Sincronizar status de resposta", desc:"Se o cliente responder, marca o follow-up como enviado"},
          ].map(opt => (
            <div key={opt.key} style={{ borderBottom:`1px solid ${O.gray100}`, paddingBottom:10, marginBottom:10 }}>
              <label style={{ display:"flex", alignItems:"flex-start", gap:10, cursor:"pointer" }}>
                <input type="checkbox" style={{ marginTop:2 }} checked={!!form[opt.key]} onChange={e=>setForm(f=>({...f,[opt.key]:e.target.checked}))} />
                <div>
                  <div style={{ fontSize:13, fontWeight:500 }}>{opt.label}</div>
                  <div style={{ fontSize:11, color:O.gray500, marginTop:1 }}>{opt.desc}</div>
                </div>
              </label>
            </div>
          ))}
          <button style={S.btn} onClick={saveForm}>Salvar automações</button>
        </div>
      </div>

      <div>
        <div style={S.card}>
          <div style={{ display:"flex", borderBottom:`1px solid ${O.gray100}`, marginBottom:20 }}>
            {Tab("connection","Testar conexão")}
            {Tab("webhook","Testar webhook")}
            {Tab("contacts","Buscar contatos")}
          </div>

          {activeTab === "connection" && (
            <div>
              <p style={{ fontSize:13, color:O.gray500, marginBottom:14 }}>Faz uma chamada real à API do Chatwoot para verificar as credenciais.</p>
              <button style={S.btn} onClick={testConnection} disabled={connStatus==="loading"}>{connStatus==="loading" ? "Conectando..." : "Testar agora"}</button>
              {connStatus && connStatus !== "loading" && (
                <div style={{ marginTop:14 }}>
                  <div style={{ padding:"12px 14px", borderRadius:10, background: connStatus.ok ? O.greenPale : O.redPale, color: connStatus.ok ? "#166534" : "#991B1B", fontSize:13 }}>
                    {connStatus.ok ? "✓ " : "✕ "}{connStatus.msg}
                  </div>
                  {connStatus.ok && connStatus.data && (
                    <div style={{ marginTop:10, background:O.gray50, borderRadius:8, padding:"10px 12px" }}>
                      <div style={{ fontSize:11, color:O.gray500, marginBottom:4 }}>Resposta da API (primeiros 500 chars):</div>
                      <pre style={{ fontSize:11, color:O.gray700, margin:0, whiteSpace:"pre-wrap", maxHeight:140, overflow:"auto" }}>{JSON.stringify(connStatus.data,null,2).slice(0,500)}</pre>
                    </div>
                  )}
                  {!connStatus.ok && <div style={{ marginTop:10, fontSize:12, color:O.gray500 }}><b>Dica CORS:</b> Se o erro for "Failed to fetch", o Chatwoot pode estar bloqueando esta origem. Configure <code>ALLOWED_ORIGINS</code> ou use um proxy reverso.</div>}
                </div>
              )}
            </div>
          )}

          {activeTab === "webhook" && (
            <div>
              <p style={{ fontSize:13, color:O.gray500, marginBottom:14 }}>Verifica webhooks registrados no Chatwoot e gera um payload de exemplo.</p>
              <button style={S.btn} onClick={testWebhook} disabled={whStatus==="loading"}>{whStatus==="loading" ? "Testando..." : "Testar webhook"}</button>
              {whStatus && whStatus !== "loading" && (
                <div style={{ marginTop:14 }}>
                  <div style={{ padding:"12px 14px", borderRadius:10, background: whStatus.ok ? O.greenPale : O.redPale, color: whStatus.ok ? "#166534" : "#991B1B", fontSize:13, marginBottom:10 }}>
                    {whStatus.ok ? "✓ " : "✕ "}{whStatus.msg}
                  </div>
                  {(whStatus.cwWebhooks||[]).length > 0 && (
                    <div style={{ marginBottom:10 }}>
                      <div style={{ fontSize:12, fontWeight:500, marginBottom:6 }}>Webhooks registrados no Chatwoot:</div>
                      {whStatus.cwWebhooks.map((w,i) => <div key={i} style={{ fontSize:11, color:O.gray700, background:O.gray50, borderRadius:6, padding:"5px 10px", marginBottom:4, wordBreak:"break-all" }}>{w.url}</div>)}
                    </div>
                  )}
                  <div style={{ fontSize:11, color:O.gray500, marginBottom:4 }}>Payload que o Chatwoot envia para nossa URL:</div>
                  <pre style={{ fontSize:10, color:O.gray700, background:O.gray50, borderRadius:8, padding:"10px 12px", margin:0, whiteSpace:"pre-wrap", maxHeight:180, overflow:"auto" }}>{JSON.stringify(whStatus.payload,null,2)}</pre>
                </div>
              )}
              <div style={{ marginTop:14, padding:"12px 14px", background:O.orangePale, borderRadius:10, fontSize:12, color:O.gray700 }}>
                <b>Para registrar o webhook no Chatwoot:</b><br />
                Settings → Integrations → Webhooks → New Webhook<br />
                Cole a URL gerada na aba <b>Webhooks</b> desta plataforma.
              </div>
            </div>
          )}

          {activeTab === "contacts" && (
            <div>
              <p style={{ fontSize:13, color:O.gray500, marginBottom:14 }}>Busca contatos diretamente na API do Chatwoot e permite importá-los.</p>
              <div style={{ display:"flex", gap:8, marginBottom:12 }}>
                <input style={{ ...S.input, flex:1 }} value={contactSearch} onChange={e=>setContactSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&searchContacts()} placeholder="Nome, e-mail ou telefone..." />
                <button style={S.btn} onClick={searchContacts} disabled={!ready||contactResults==="loading"}>{contactResults==="loading"?"...":"Buscar"}</button>
              </div>
              {!ready && <div style={{ fontSize:12, color:O.orange }}>⚠ Salve as credenciais antes de buscar.</div>}
              {contactResults==="loading" && <div style={{ fontSize:13, color:O.gray500, padding:"12px 0" }}>Buscando no Chatwoot...</div>}
              {Array.isArray(contactResults) && contactResults.length===0 && <div style={{ fontSize:13, color:O.gray500 }}>Nenhum contato encontrado.</div>}
              {Array.isArray(contactResults) && contactResults.length > 0 && (
                <div style={{ display:"flex", flexDirection:"column", gap:6, maxHeight:320, overflowY:"auto" }}>
                  {contactResults.slice(0,30).map(c => {
                    const in_ = clients.find(cl => cl.chatwootId===c.id || cl.phone===c.phone_number);
                    return (
                      <div key={c.id} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"8px 10px", background:O.gray50, borderRadius:8 }}>
                        <div>
                          <div style={{ fontSize:13, fontWeight:500 }}>{c.name||"Sem nome"}</div>
                          <div style={{ fontSize:11, color:O.gray500 }}>{[c.phone_number,c.email].filter(Boolean).join(" · ")}</div>
                        </div>
                        {in_ ? <span style={{ ...S.tag, background:O.greenPale, color:"#166534" }}>Importado</span>
                              : <button style={{ ...S.btnGhost, padding:"4px 12px", fontSize:12 }} disabled={importing[c.id]} onClick={()=>importContact(c)}>{importing[c.id]?"✓":"+ Importar"}</button>}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </div>

        <div style={{ ...S.card, marginTop:16, background:O.orangePale, border:`1px solid ${O.orangeBorder}` }}>
          <h3 style={{ fontSize:13, fontWeight:600, color:O.black, margin:"0 0 10px" }}>Como encontrar as credenciais</h3>
          <div style={{ fontSize:12, color:O.gray700, lineHeight:1.9 }}>
            1. Acesse seu Chatwoot<br />
            2. Clique no <b>perfil</b> (canto inferior esquerdo) → <b>Profile Settings</b><br />
            3. Role até <b>Access Token</b> e copie<br />
            4. O <b>Account ID</b> está em <b>Settings → Account Settings</b>
          </div>
        </div>
      </div>
    </div>
  );
}

function WhaticketConfig({ cfg, onChange }) {
  const [form, setForm] = useState(cfg);
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState(null);

  function save() { onChange({...form, updatedAt:now()}); alert("Configuração salva!"); }

  async function testConnection() {
    if (!form.apiUrl || !form.apiToken) return alert("Preencha a URL e o token antes de testar.");
    setTesting(true);
    await new Promise(r=>setTimeout(r,1200));
    setTestResult({ok:true, msg:"Conexão testada (simulada). Substitua pela URL real da sua instância."});
    setTesting(false);
  }

  return (
    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:24 }}>
      <div>
        <div style={S.card}>
          <h3 style={{ fontSize:15, fontWeight:600, color:O.black, margin:"0 0 16px" }}>Credenciais WhatTicket</h3>
          <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", marginBottom:16 }}>
            <input type="checkbox" checked={!!form.enabled} onChange={e=>setForm(f=>({...f,enabled:e.target.checked}))} />
            <span style={{ fontSize:13, fontWeight:500 }}>Integração ativa</span>
          </label>
          <Field label="URL da instância"><input style={S.input} value={form.apiUrl||""} onChange={e=>setForm(f=>({...f,apiUrl:e.target.value}))} placeholder="https://seu-whaticket.com" /></Field>
          <Field label="Token de API"><input type="password" style={S.input} value={form.apiToken||""} onChange={e=>setForm(f=>({...f,apiToken:e.target.value}))} placeholder="Bearer token" /></Field>
          <Field label="ID da fila padrão"><input style={S.input} value={form.queueId||""} onChange={e=>setForm(f=>({...f,queueId:e.target.value}))} placeholder="ID da fila de atendimento" /></Field>
          <div style={{ display:"flex", gap:8, marginTop:4 }}>
            <button style={S.btn} onClick={save}>Salvar</button>
            <button style={S.btnOutline} onClick={testConnection} disabled={testing}>{testing?"Testando...":"Testar conexão"}</button>
          </div>
          {testResult && <div style={{ marginTop:12, padding:"10px 14px", borderRadius:10, background: testResult.ok?O.greenPale:O.redPale, color: testResult.ok?"#166534":"#991B1B", fontSize:13 }}>{testResult.msg}</div>}
          <div style={{ marginTop:18, padding:14, background:O.orangePale, borderRadius:10 }}>
            <h4 style={{ fontSize:13, fontWeight:600, margin:"0 0 8px" }}>Automações</h4>
            {[{key:"autoImport",label:"Importar contatos automaticamente"},{key:"autoSchedule",label:"Agendar follow-up em novos tickets"}].map(opt => (
              <label key={opt.key} style={{ display:"flex", alignItems:"center", gap:8, marginBottom:8, cursor:"pointer" }}>
                <input type="checkbox" checked={!!form[opt.key]} onChange={e=>setForm(f=>({...f,[opt.key]:e.target.checked}))} />
                <span style={{ fontSize:13 }}>{opt.label}</span>
              </label>
            ))}
          </div>
        </div>
      </div>
      <div style={{ ...S.card, background:O.orangePale, border:`1px solid ${O.orangeBorder}` }}>
        <h3 style={{ fontSize:14, fontWeight:600, color:O.black, margin:"0 0 12px" }}>Como configurar no WhatTicket</h3>
        <div style={{ fontSize:13, color:O.gray700, lineHeight:1.8 }}>
          <b>1.</b> Acesse WhatTicket → <b>Configurações → Conexões → API</b><br /><br />
          <b>2.</b> Gere o <b>token de acesso</b> e cole aqui<br /><br />
          <b>3.</b> Para webhooks: <b>Configurações → Webhooks</b><br /><br />
          <b>4.</b> Cole a URL da aba <b>Webhooks</b> desta plataforma<br /><br />
          <b>5.</b> Ative os eventos: <b>contact.created, ticket.created</b>
        </div>
      </div>
    </div>
  );
}

// ─── Settings ────────────────────────────────────────────────────────────────
function Settings({ accountId }) {
  const [settings, setSettings] = useStore(accountId, "settings", { accountName:"", timezone:"America/Sao_Paulo", sendWindow:{from:"08:00",to:"18:00"}, notifyEmail:"", retryFailed:true, retryCount:3 });

  return (
    <div>
      <div style={{ marginBottom:24 }}>
        <h1 style={{ fontSize:24, fontWeight:600, color:O.black, margin:0 }}>Configurações</h1>
        <p style={{ fontSize:14, color:O.gray500, marginTop:4 }}>Conta: <b>{accountId}</b></p>
      </div>
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:18 }}>
        <div style={S.card}>
          <h3 style={{ fontSize:15, fontWeight:600, marginBottom:16 }}>Dados da conta</h3>
          <Field label="Nome da conta"><input style={S.input} value={settings.accountName||""} onChange={e=>setSettings(s=>({...s,accountName:e.target.value}))} placeholder="Ex: Minha Empresa" /></Field>
          <Field label="Fuso horário">
            <select style={S.input} value={settings.timezone} onChange={e=>setSettings(s=>({...s,timezone:e.target.value}))}>
              <option value="America/Sao_Paulo">America/Sao_Paulo (BRT)</option>
              <option value="America/Fortaleza">America/Fortaleza</option>
              <option value="America/Manaus">America/Manaus</option>
              <option value="America/Belem">America/Belem</option>
            </select>
          </Field>
          <Field label="E-mail para notificações"><input style={S.input} value={settings.notifyEmail||""} onChange={e=>setSettings(s=>({...s,notifyEmail:e.target.value}))} placeholder="notificacoes@empresa.com" /></Field>
        </div>
        <div style={S.card}>
          <h3 style={{ fontSize:15, fontWeight:600, marginBottom:16 }}>Janela de envio</h3>
          <p style={{ fontSize:13, color:O.gray500, marginBottom:14 }}>Horário permitido para envio de mensagens</p>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12 }}>
            <Field label="De"><input type="time" style={S.input} value={settings.sendWindow?.from||"08:00"} onChange={e=>setSettings(s=>({...s,sendWindow:{...s.sendWindow,from:e.target.value}}))} /></Field>
            <Field label="Até"><input type="time" style={S.input} value={settings.sendWindow?.to||"18:00"} onChange={e=>setSettings(s=>({...s,sendWindow:{...s.sendWindow,to:e.target.value}}))} /></Field>
          </div>
          <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", marginTop:8 }}>
            <input type="checkbox" checked={!!settings.retryFailed} onChange={e=>setSettings(s=>({...s,retryFailed:e.target.checked}))} />
            <span style={{ fontSize:13 }}>Retentar envios que falharam</span>
          </label>
          {settings.retryFailed && (
            <Field label="Nº de tentativas" style={{ marginTop:12 }}>
              <input type="number" min={1} max={10} style={{ ...S.input, width:80 }} value={settings.retryCount||3} onChange={e=>setSettings(s=>({...s,retryCount:parseInt(e.target.value)||3}))} />
            </Field>
          )}
        </div>
        <div style={{ ...S.card, gridColumn:"1/-1" }}>
          <h3 style={{ fontSize:15, fontWeight:600, marginBottom:14 }}>Identificação desta conta</h3>
          <div style={{ display:"flex", gap:16, alignItems:"center" }}>
            <div style={{ background:O.orangePale, borderRadius:12, padding:"12px 20px" }}>
              <div style={{ fontSize:12, color:O.gray500, marginBottom:2 }}>URL desta conta</div>
              <code style={{ fontSize:14, color:O.orange, fontWeight:500 }}>{window.location.origin}/{accountId}</code>
            </div>
            <div style={{ fontSize:13, color:O.gray500 }}>Compartilhe esta URL com sua equipe. Sem login necessário — o ID da conta é a chave de acesso.</div>
          </div>
        </div>
      </div>
      <div style={{ marginTop:20 }}>
        <button style={S.btn} onClick={()=>alert("Configurações salvas!")}>Salvar configurações</button>
      </div>
    </div>
  );
}

// ─── Account Selector ────────────────────────────────────────────────────────
function AccountSelector({ onEnter }) {
  const [val, setVal] = useState("conta-1");
  const suggestions = ["conta-1","conta-2","empresa-abc","minha-loja"];
  return (
    <div style={{ minHeight:"100vh", background:O.white, display:"flex", alignItems:"center", justifyContent:"center" }}>
      <div style={{ width:400, textAlign:"center" }}>
        <img src={LOGO} alt="FollowUp" style={{ width:80, height:80, objectFit:"contain", margin:"0 auto 20px", display:"block" }} />
        <h1 style={{ fontSize:28, fontWeight:600, color:O.black, marginBottom:6 }}>FollowUp</h1>
        <p style={{ fontSize:14, color:O.gray500, marginBottom:32 }}>Plataforma de follow-up multicanal</p>
        <div style={{ ...S.card, textAlign:"left" }}>
          <p style={{ fontSize:13, color:O.gray700, marginBottom:16, marginTop:0 }}>Acesse uma conta digitando o ID abaixo. Não precisa de login.</p>
          <Field label="ID da conta">
            <input style={S.input} value={val} onChange={e=>setVal(e.target.value.replace(/\s/g,"-").toLowerCase())} onKeyDown={e=>e.key==="Enter"&&val&&onEnter(val)} placeholder="ex: conta-1, minha-empresa" />
          </Field>
          <button style={{ ...S.btn, width:"100%", justifyContent:"center" }} onClick={()=>val&&onEnter(val)}>Entrar na conta</button>
          <div style={{ marginTop:14, fontSize:12, color:O.gray400 }}>
            Exemplos rápidos:
            <div style={{ display:"flex", gap:6, marginTop:6, flexWrap:"wrap" }}>
              {suggestions.map(s => <button key={s} style={{ ...S.btnGhost, padding:"3px 10px", fontSize:11 }} onClick={()=>setVal(s)}>{s}</button>)}
            </div>
          </div>
        </div>
        <div style={{ marginTop:14, fontSize:11, color:O.gray400 }}>Cada conta é isolada. URL: <code style={{ color:O.orange }}>/{"{id}"}</code></div>
      </div>
    </div>
  );
}

// ─── App Root ─────────────────────────────────────────────────────────────────
const PAGES = { dashboard: Dashboard, clients: Clients, messages: Messages, schedules: Schedules, webhooks: Webhooks, integrations: Integrations, settings: Settings };

export default function App() {
  const [accountId, setAccountId] = useState(() => {
    const m = window.location.pathname.match(/^\/([a-z0-9-]+)/);
    return m ? m[1] : null;
  });
  const [page, setPage] = useState("dashboard");

  useEffect(() => {
    if (accountId) {
      document.title = `FollowUp — ${accountId}`;
      window.history.replaceState({}, "", `/${accountId}`);
    }
  }, [accountId]);

  if (!accountId) return <AccountSelector onEnter={setAccountId} />;

  const Page = PAGES[page] || Dashboard;
  return (
    <div style={{ fontFamily:"-apple-system,BlinkMacSystemFont,'SF Pro Display','Helvetica Neue',Arial,sans-serif", background:O.gray50, minHeight:"100vh" }}>
      <Sidebar page={page} setPage={setPage} accountId={accountId} />
      <main style={{ marginLeft:220, padding:"40px 40px 60px", minHeight:"100vh" }}>
        <Page accountId={accountId} />
      </main>
    </div>
  );
}
